140 | //
141 | // Set current segment to the segment containing the specified line number.
142 | // Based on wksp_position() from prototype/r.edit.c
143 | //
144 | // This method positions the workspace by updating:
145 | //   - cursegm_: points to the segment containing the line
146 | //   - segmline_: first line number in the current segment
147 | //   - line_: the absolute line number requested
148 | //
149 | // The method walks the segment chain forward or backward to find the segment
150 | // containing the requested line.
151 | //
152 | // Returns:
153 | //   0 - success, cursegm_ and segmline_ updated to the correct segment
154 | //   1 - line number is beyond end of file (hit tail segment)
155 | //
156 | // Throws:
157 | //   std::runtime_error for invalid line numbers or corrupted segment chains
158 | //
159 | int Workspace::set_current_segment(int lno)
160 | {
161 |     // Validate input: negative line numbers are invalid
162 |     if (lno < 0)
163 |         throw std::runtime_error("set_current_segment: negative line number");
164 | 
165 |     if (cursegm_ == segments_.end())
166 |         throw std::runtime_error("set_current_segment: empty workspace");
167 | 
168 |     // Move forward to find the segment containing lno
169 |     while (lno >= position.segmline + cursegm_->nlines) {
170 |         if (cursegm_->fdesc == 0) {
171 |             // Hit tail segment - line is beyond end of file
172 |             // Return 1 to signal that line is beyond end of file
173 |             position.line = position.segmline;
174 |             return 1;
175 |         }
176 |         position.segmline += cursegm_->nlines;
177 | 
178 |         // Check if there's a next segment before moving
179 |         auto next_it = std::next(cursegm_);
180 |         if (next_it == segments_.end()) {
181 |             throw std::runtime_error("set_current_segment: null segment in chain");
182 |         }
183 |         ++cursegm_;
184 |     }
185 | 
186 |     // Move backward to find the segment containing lno
187 |     while (lno < position.segmline) {
188 |         if (cursegm_ == segments_.begin())
189 |             throw std::runtime_error("set_current_segment: null previous segment");
190 |         --cursegm_;
191 |         position.segmline -= cursegm_->nlines;
192 |     }
193 | 
194 |     // Consistency check: segmline should not be negative
195 |     if (position.segmline < 0) {
196 |         throw std::runtime_error("set_current_segment: line count lost (segmline < 0)");
197 |     }
198 | 
199 |     // Update workspace state
200 |     position.line = lno;
201 | 
202 |     return 0;
203 | }
