224 | //
225 | // Build segment chain from file descriptor.
226 | //
227 | void Workspace::load_file(int fd)
228 | {
229 |     file_state.nlines = 0;
230 | 
231 |     // Clean up old chain
232 |     cleanup_segments();
233 | 
234 |     // Build segment chain by reading file
235 |     // Clear any existing segments list
236 |     segments_.clear();
237 | 
238 |     char read_buf[8192];
239 |     int buf_count    = 0;
240 |     int buf_next     = 0;
241 |     long file_offset = 0;
242 | 
243 |     // Temporary segment to build data
244 |     Segment temp_seg;
245 |     int lines_in_seg = 0;
246 |     long seg_seek    = 0;
247 | 
248 |     for (;;) {
249 |         // Read buffer if needed
250 |         if (buf_next >= buf_count) {
251 |             buf_next  = 0;
252 |             buf_count = read(fd, read_buf, sizeof(read_buf));
253 |             if (buf_count <= 0) {
254 |                 // EOF
255 |                 if (lines_in_seg > 0) {
256 |                     // Create final segment in list
257 |                     segments_.emplace_back();
258 |                     Segment &seg = segments_.back();
259 |                     seg.nlines   = lines_in_seg;
260 |                     seg.fdesc    = fd;
261 |                     seg.seek     = seg_seek;
262 |                     seg.sizes    = std::move(temp_seg.sizes);
263 | 
264 |                     file_state.nlines += lines_in_seg;
265 |                 }
266 |                 break;
267 |             }
268 |         }
269 | 
270 |         // Process line - handle lines that span buffer boundaries
271 |         int line_len       = 0;
272 |         bool line_complete = false;
273 | 
274 |         while (!line_complete) {
275 |             char *line_start = read_buf + buf_next;
276 |             char *line_end   = line_start;
277 | 
278 |             // Find line end
279 |             while (buf_next < buf_count && *line_end != '\n') {
280 |                 ++line_end, ++buf_next;
281 |             }
282 | 
283 |             line_len += (line_end - line_start);
284 | 
285 |             if (buf_next < buf_count) {
286 |                 // Found newline in current buffer
287 |                 line_len += 1; // include newline
288 |                 ++buf_next;    // skip '\n'
289 |                 line_complete = true;
290 |             } else {
291 |                 // No newline found - line continues in next buffer
292 |                 // More data to read - reload buffer
293 |                 buf_next  = 0;
294 |                 buf_count = read(fd, read_buf, sizeof(read_buf));
295 |                 if (buf_count <= 0) {
296 |                     // EOF - treat incomplete line as complete
297 |                     line_len += 1; // add trailing newline
298 |                     line_complete = true;
299 |                 }
300 |                 // If buffer was successfully read, continue loop to process next buffer
301 |             }
302 |         }
303 | 
304 |         // Store line length in segment data
305 |         if (lines_in_seg == 0) {
306 |             seg_seek = file_offset;
307 |         }
308 | 
309 |         temp_seg.sizes.push_back(line_len);
310 | 
311 |         ++lines_in_seg;
312 |         file_offset += line_len;
313 | 
314 |         // Create new segment if we've hit limits
315 |         if (lines_in_seg >= 127 || temp_seg.sizes.size() >= 4000) {
316 |             segments_.emplace_back();
